function AngleDiagram({kind}:{kind:Diagram}){
  if(kind==='multi')return <div className="angle-diagram" aria-label="Три луча OA, OB и OC с общей вершиной O"><svg viewBox="0 0 600 300" role="img"><line className="angle-ray" x1="290" y1="240" x2="90" y2="90"/><line className="angle-ray" x1="290" y1="240" x2="300" y2="45"/><line className="angle-ray" x1="290" y1="240" x2="520" y2="110"/><circle className="angle-point" cx="290" cy="240" r="6"/><text className="angle-label" x="272" y="275">O</text><text className="angle-label" x="65" y="82">A</text><text className="angle-label" x="292" y="35">B</text><text className="angle-label" x="530" y="105">C</text><path className="angle-arc" d="M250 210 Q287 170 298 185"/><path className="angle-arc" d="M304 185 Q355 177 375 192"/></svg><span className="angle-caption">Из O выходят три луча: OA, OB, OC</span></div>;
  if(kind==='construction')return <div className="angle-diagram" aria-label="Угол KLM с вершиной L"><svg viewBox="0 0 600 300" role="img"><line className="angle-ray" x1="285" y1="235" x2="105" y2="80"/><line className="angle-ray" x1="285" y1="235" x2="515" y2="105"/><circle className="angle-point" cx="285" cy="235" r="6"/><text className="angle-label" x="90" y="72">K</text><text className="angle-label" x="270" y="272">L</text><text className="angle-label" x="525" y="102">M</text><path className="angle-arc" d="M244 200 Q286 157 339 204"/></svg><span className="angle-caption">∠KLM: L — вершина, LK и LM — стороны</span></div>;
  return <div className="angle-diagram" aria-label="Угол ABC с вершиной B"><svg viewBox="0 0 600 300" role="img"><line className="angle-ray" x1="290" y1="235" x2="95" y2="85"/><line className="angle-ray" x1="290" y1="235" x2="515" y2="100"/><circle className="angle-point" cx="290" cy="235" r="6"/><text className="angle-label" x="75" y="78">A</text><text className="angle-label" x="272" y="272">B</text><text className="angle-label" x="525" y="98">C</text><path className="angle-arc" d="M250 205 Q290 160 343 202"/></svg><span className="angle-caption">{kind==='reverse'?'Один угол: ∠ABC = ∠CBA':'∠ABC: B — вершина, BA и BC — стороны'}</span></div>;
}

function loadSaved():Saved{try{const raw=localStorage.getItem(KEY);if(!raw)return{version:1,stageIndex:0,responses:{},checked:{},results:{}};const parsed=JSON.parse(raw) as Partial<Saved>;return{version:1,stageIndex:Math.min(Math.max(Number(parsed.stageIndex)||0,0),lessonThirtySevenStages.length-1),responses:parsed.responses??{},checked:parsed.checked??{},results:parsed.results??{}}}catch{return{version:1,stageIndex:0,responses:{},checked:{},results:{}}}}
function stopNarration(){window.dispatchEvent(new CustomEvent('mathnikita-stop-narration'));if('speechSynthesis'in window)window.speechSynthesis.cancel()}

export function AngleNotationPlayer(){
  const initial=useMemo(loadSaved,[]);const[stageIndex,setStageIndex]=useState(initial.stageIndex);const[responses,setResponses]=useState<Record<string,string>>(initial.responses);const[checked,setChecked]=useState<Record<string,boolean>>(initial.checked);const[results,setResults]=useState<Record<string,boolean>>(initial.results);const stage=lessonThirtySevenStages[stageIndex];
  useEffect(()=>{localStorage.setItem(KEY,JSON.stringify({version:1,stageIndex,responses,checked,results} satisfies Saved))},[stageIndex,responses,checked,results]);
  useEffect(()=>{const handler=(event:Event)=>{const detail=(event as CustomEvent<StageJumpDetail>).detail;if(detail?.lessonNumber!==37||typeof detail.stageIndex!=='number')return;stopNarration();setStageIndex(Math.min(Math.max(Math.trunc(detail.stageIndex),0),lessonThirtySevenStages.length-1))};window.addEventListener('mathnikita-go-to-stage',handler);return()=>window.removeEventListener('mathnikita-go-to-stage',handler)},[]);
  const activity=stage.activity;const response=activity?responses[activity.id]??'':'';const isChecked=activity?Boolean(checked[activity.id]):false;const isCorrect=activity?Boolean(results[activity.id]):false;
  function changeStage(next:number){stopNarration();setStageIndex(Math.min(Math.max(next,0),lessonThirtySevenStages.length-1));window.scrollTo({top:0,behavior:'smooth'})}
  function checkAnswer(){if(!activity||!response.trim())return;const correct=normalize(response)===normalize(activity.answer);setChecked(previous=>({...previous,[activity.id]:true}));setResults(previous=>({...previous,[activity.id]:correct}))}
  function setResponse(value:string){if(!activity)return;setResponses(previous=>({...previous,[activity.id]:value}));setChecked(previous=>({...previous,[activity.id]:false}))}
  return <section className="lesson-player angle-lesson-player" aria-label="Урок 37. Угол. Обозначение углов"><article className={`interactive-stage stage-${stage.kind} ${stage.kind==='summary'?'stage-summary':''}`} data-stage-id={stage.id}><div className="stage-copy"><span>{stage.eyebrow}</span><h2>{stage.title}</h2><p>{stage.body}</p>{stage.note?<aside className="theory-note">{stage.note}</aside>:null}</div>{stage.diagram?<AngleDiagram kind={stage.diagram}/>:null}{activity?<div className="activity-area"><h3>{activity.prompt}</h3>{activity.type==='choice'?<div className="choice-grid">{activity.options?.map(option=><button type="button" key={option} className={response===option?'selected':''} onClick={()=>setResponse(option)}>{option}</button>)}</div>:<div className="inline-answer"><input value={response} onChange={event=>setResponse(event.target.value)} onKeyDown={event=>{if(event.key==='Enter')checkAnswer()}} placeholder={activity.placeholder??'Ответ'} autoCapitalize="characters"/></div>}<button type="button" className="check-button" disabled={!response.trim()} onClick={checkAnswer}>Проверить</button>{isChecked?<div className={`instant-feedback ${isCorrect?'good':'bad'}`} data-explanation={activity.explanation}><b>{isCorrect?'Верно!':'Проверь ещё раз'}</b><span>{isCorrect?activity.explanation:activity.hint}</span></div>:null}</div>:null}{stage.kind==='summary'?<div className="summary-card"><strong>§ 11 · урок 1 из 2 завершён</strong><span>Вершина · стороны угла · трёхбуквенная запись · однозначные обозначения</span></div>:null}<div className="lesson-controls"><button type="button" onClick={()=>changeStage(stageIndex-1)} disabled={stageIndex===0}>← Назад</button><span>Этап {stageIndex+1} из {lessonThirtySevenStages.length}</span><button type="button" className="primary" onClick={()=>changeStage(stageIndex+1)} disabled={stageIndex===lessonThirtySevenStages.length-1||(Boolean(activity)&&(!isChecked||!isCorrect))}>{stageIndex===lessonThirtySevenStages.length-1?'Готово':'Дальше →'}</button></div></article></section>
}
